package repository

import (
	"context"
	"distributed-queue/internal/domain"
	"distributed-queue/pkg/redis/metrics"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// CreateJob appends a PENDING task to a DRAFT workflow.
// It records dependencies without creating an outbox publication.
// task.ID is generated by the caller (uuid.New()) rather than by Postgres,
// because the same ID is used as the Redis queue member — Redis and
// Postgres need to agree on task identity before either one sees the task.
func (r *JobRepository) CreateJob(ctx context.Context, queueName string, task Task) (JobRow, error) {
	if err := task.ExecutionContract.Validate(); err != nil {
		return JobRow{}, fmt.Errorf("invalid execution contract: %w", err)
	}
	if task.ExecutionContract.TaskType != task.TaskType {
		return JobRow{}, errors.New("execution contract task type does not match task")
	}
	if task.EffectKey == uuid.Nil {
		return JobRow{}, errors.New("effect key is required")
	}
	contractJSON, err := json.Marshal(task.ExecutionContract)
	if err != nil {
		return JobRow{}, fmt.Errorf("failed to encode execution contract: %w", err)
	}

	payload := task.Payload
	if payload == nil {
		payload = json.RawMessage(`{}`)
	}

	tx, err := r.pool.Begin(ctx)
	if err != nil {
		metrics.JobRepoErrors.WithLabelValues(queueName, "CreateJob").Inc()
		return JobRow{}, fmt.Errorf("failed to begin transaction: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }() // Rollback is a no-op after commit.

	if _, err := tx.Exec(ctx,
		`SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0));`,
		task.WorkflowID,
	); err != nil {
		return JobRow{}, fmt.Errorf("failed to lock workflow: %w", err)
	}

	var workflowStatus domain.WorkflowStatus
	var sealedAt, draftExpiresAt *time.Time
	var dbNow time.Time
	err = tx.QueryRow(ctx,
		`SELECT status,sealed_at,draft_expires_at,clock_timestamp() FROM workflows WHERE id = $1`,
		task.WorkflowID,
	).Scan(&workflowStatus, &sealedAt, &draftExpiresAt, &dbNow)
	if err != nil {
		return JobRow{}, fmt.Errorf("failed to read workflow: %w", err)
	}
	if sealedAt != nil {
		return JobRow{}, ErrWorkflowSealed
	}
	if workflowStatus == domain.WorkflowStatusDraft {
		if draftExpiresAt == nil || !draftExpiresAt.After(dbNow) {
			return JobRow{}, ErrDraftExpired
		}
	} else if workflowStatus != domain.WorkflowStatusDraft {
		return JobRow{}, ErrWorkflowNotDraft
	}
	status := domain.TaskStatusPending
	if len(task.ParentIDs) > 0 {
		var parentCount int
		if err := tx.QueryRow(ctx, `
			SELECT COUNT(*) FROM processed_jobs
			WHERE workflow_id = $1 AND id = ANY($2::uuid[]) AND id <> $3
		`, task.WorkflowID, task.ParentIDs, task.ID).Scan(&parentCount); err != nil {
			return JobRow{}, fmt.Errorf("failed to validate task parents: %w", err)
		}
		if parentCount != len(task.ParentIDs) {
			return JobRow{}, ErrInvalidParents
		}
	}
	var jobRow JobRow
	// Insert the job
	query := `
		INSERT INTO processed_jobs (id, workflow_id, task_type, status, task_details, max_retries,
		                            execution_contract, effect_key)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
		RETURNING id, workflow_id, task_type, tenant_id, execution_contract, effect_key,
		          status, task_details, current_retries, max_retries, error_log, created_at, processed_at, available_at;
	`
	err = tx.QueryRow(ctx, query,
		task.ID, task.WorkflowID, task.TaskType, status, payload, task.ExecutionContract.MaxAttempts,
		contractJSON, task.EffectKey,
	).Scan(
		&jobRow.ID, &jobRow.WorkflowID, &jobRow.TaskType,
		&jobRow.TenantID, &jobRow.ExecutionContract, &jobRow.EffectKey,
		&jobRow.Status, &jobRow.Payload, &jobRow.CurrentRetries, &jobRow.MaxRetries, &jobRow.ErrorLog,
		&jobRow.CreatedAt, &jobRow.ProcessedAt, &jobRow.AvailableAt,
	)
	if err != nil {
		metrics.JobRepoErrors.WithLabelValues(queueName, "CreateJob").Inc()
		return JobRow{}, fmt.Errorf("failed to create job %s: %w", task.ID, err)
	}

	// Insert parent dependencies if any
	if len(task.ParentIDs) > 0 {
		depQuery := `
			INSERT INTO job_dependencies (child_job_id, parent_job_id)
			VALUES ($1, $2);
		`
		for _, parentID := range task.ParentIDs {
			_, err = tx.Exec(ctx, depQuery, task.ID, parentID)
			if err != nil {
				metrics.JobRepoErrors.WithLabelValues(queueName, "CreateJob").Inc()
				return JobRow{}, fmt.Errorf("failed to create dependency %s -> %s: %w", parentID, task.ID, err)
			}
			jobRow.ParentIDs = append(jobRow.ParentIDs, parentID)
		}
	}
	if err := tx.Commit(ctx); err != nil {
		metrics.JobRepoErrors.WithLabelValues(queueName, "CreateJob").Inc()
		return JobRow{}, fmt.Errorf("failed to commit job creation: %w", err)
	}
	return jobRow, nil
}

func (r *JobRepository) GetTask(ctx context.Context, taskID uuid.UUID) (JobRow, error) {
	if taskID == uuid.Nil {
		return JobRow{}, fmt.Errorf("taskID is nil")
	}

	var task JobRow
	query := `SELECT id, workflow_id, task_type, tenant_id, execution_contract, effect_key, status,task_details, current_retries, max_retries,
          error_log, created_at, processed_at, available_at
		  FROM processed_jobs
		  WHERE id = $1;`
	err := r.pool.QueryRow(ctx, query, taskID).Scan(
		&task.ID, &task.WorkflowID, &task.TaskType,
		&task.TenantID, &task.ExecutionContract, &task.EffectKey,
		&task.Status, &task.Payload,
		&task.CurrentRetries, &task.MaxRetries,
		&task.ErrorLog, &task.CreatedAt, &task.ProcessedAt, &task.AvailableAt,
	)
	if err != nil {
		return JobRow{}, fmt.Errorf("failed to get Task for ID %s: %w", taskID, err)
	}

	var rows pgx.Rows
	rows, err = r.pool.Query(ctx, `SELECT parent_job_id FROM job_dependencies WHERE child_job_id=$1;`, taskID)
	if err != nil {
		return JobRow{}, fmt.Errorf("failed to get parent IDs for task %s: %w", taskID, err)
	}
	defer rows.Close()
	for rows.Next() {
		var parentID uuid.UUID
		if err := rows.Scan(&parentID); err != nil {
			return JobRow{}, fmt.Errorf("failed to scan parent ID: %w", err)
		}
		task.ParentIDs = append(task.ParentIDs, parentID)
	}
	if err := rows.Err(); err != nil {
		return JobRow{}, fmt.Errorf("parent IDs iteration error: %w", err)
	}
	return task, nil
}

// GetWorkflowID retrieves the workflow_id for a given task.
func (r *JobRepository) GetWorkflowID(ctx context.Context, taskID string) (uuid.UUID, error) {
	id, err := uuid.Parse(taskID)
	if err != nil {
		return uuid.Nil, fmt.Errorf("taskID %q is not a valid UUID: %w", taskID, err)
	}

	var workflowID uuid.UUID
	query := `SELECT workflow_id FROM processed_jobs WHERE id = $1;`
	err = r.pool.QueryRow(ctx, query, id).Scan(&workflowID)
	if err != nil {
		return uuid.Nil, fmt.Errorf("failed to get workflow_id for task %s: %w", taskID, err)
	}
	return workflowID, nil
}
